function trimSamples(samples, sr, s0, s1){
  if(s0==null)s0=0; if(s1==null)s1=samples.length/sr;
  if(s0<0)s0=0; if(s1>samples.length/sr)s1=samples.length/sr;
  if(s1<s0)s1=s0;
  var i0=Math.floor(s0*sr), i1=Math.floor(s1*sr);
  return samples.subarray(i0, i1);
}

var EXPORTS={trimSamples:trimSamples};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.AudioTrimForgePure = EXPORTS; }
